# -*- coding: utf-8 -*-
"""data_proj_cards_f2.py —— ㉓ SSD1306 OLED 显示（I2C）引导向导"""

GUIDE_P23_OLED = r"""{m:"引导", t:"guide", n:"🧭 ㉓ OLED 显示引导（从一堆散落函数到一块能跑起来的屏）",
 d:"从「I2C 上到底有没有这块屏」开始，一步一步把 0.96 寸 SSD1306 点亮并跑起来：先用 SYS_I2C_Scan 确认 0x3C 在总线上，再吃透控制字节（0x00 命令 / 0x40 数据）和页寻址这套显存模型，这是初学 OLED 最容易卡住的两道坎；然后照源码写初始化序列并点亮，用「画一个点」实测位序，接着画图元、显示字符与数字，最后解决本项目真正难的两个人问题：整帧刷新必须一次性持递归互斥量（否则屏上出现半新半旧的撕裂横条），以及把这块屏接进 FreeRTOS 显示任务、和传感器数据对接。全程讲清为什么这么做、以及踩过的问题。",
 g:"对应模块与平台：板2 oled.c / oled.h（UTF-8，OLED_* 接口，8×16 字库，逐页刷新=40 次 I2C 事务）；板1 sys_oled.c / sys_oled.h（GBK，SYS_OLED_* 接口，内置 8×8 字库，整帧一次性流水发送）。STM32F407 + 标准外设库 SPL + FreeRTOS，SSD1306 128×64 单色，I2C1 = PB8/PB9，7 位地址 0x3C（SA0 上拉时为 0x3D），模块板载电荷泵、3.3V 直接可用，通常只需 SDA/SCL/VCC/GND 四根线。",
 k:"SSD1306 OLED 0.96寸 128x64 单色 I2C I2C1 PB8 PB9 0x3C 0x3D 7位地址 8位地址 0x78 控制字节 control byte 0x00 0x40 页寻址 page addressing 水平寻址 显存 framebuffer 1024字节 脏页刷新 整帧刷新 Refresh 40次事务 撕裂 递归互斥量 SYS_I2C_Lock SYS_I2C_Unlock 电荷泵 0x8D 0x14 对比度 0x81 段重映射 0xA1 扫描方向 0xC8 复用率 0xA8 预充电 0xD9 VCOMH 字库 8x16 8x8 列行式 低位在上 取模 反显 inv DrawPoint DrawLine DrawRect DrawCircle ShowChar ShowString ShowNum ShowFixed 定长对齐 FreeRTOS 显示任务 多任务 上拉 400kHz 性能优化 OLED_Init OLED_Refresh SYS_OLED_Init SYS_I2C_Scan SYS_I2C_IsDeviceReady SYS_I2C_WriteBytes 相关",
 e:"/* ============================================================\n *  SSD1306 OLED 128x64（I2C），引导 10 步的成品代码（可编译）\n *  平台：STM32F407 · 标准外设库 SPL · FreeRTOS\n *  板2：I2C1 PB8/PB9（与板载 24C02 0x50 / MPU6050 0x68 共用）· 地址 0x3C\n *  接口：本文件写板2 的 OLED_* 一套；板1 的 SYS_OLED_* 名字与参数不同，\n *        见每一步的「相关条目」与「常见问题」两条注释。\n * ============================================================ */\n#include \"stm32f4xx.h\"\n#include \"oled.h\"            /* OLED_Init / ClearBuffer / Refresh / 绘图 / 文字 */\n#include \"sys_i2c.h\"         /* SYS_I2C_Init / Scan / Lock / Unlock / ErrStr */\n#include \"sys_delay.h\"       /* SYS_DelayMs */\n#include \"FreeRTOS.h\"\n#include \"task.h\"\n#include \"queue.h\"\n\n#include <string.h>\n#include <stdio.h>\n\n/* ---------------- 一、常量与全局 ---------------- */\n#define OLED_WIDTH_B   128U\n#define OLED_HEIGHT_B  64U\n#define OLED_PAGES_B   8U\n#define PANEL_LINE     \"------------------------\"   /* 24 个 '-'，画分隔线 */\n\ntypedef struct {\n    float temp_c;\n    float humi_rh;\n    float press_hpa;\n    uint16_t light_lx;\n    int16_t mpu_ax;          /* 加速度原始值，直接显示看趋势 */\n    uint8_t online;\n} SysEnv_t;\n\nstatic QueueHandle_t s_env_q = NULL;\nstatic uint32_t      s_oled_tick_last  = 0U;\nstatic uint32_t      s_oled_refresh_ok = 0U;\nstatic uint32_t      s_oled_refresh_bad= 0U;\n\n/* 上一次显示的文本快照：脏页刷新的判据（哪一行变了才重画并重刷那一页） */\nstatic char s_line_last[4][24];\n\n/* ---------------- 二、板上电第一步：先确认总线上有谁 ---------------- */\nstatic uint8_t oled_probe(void)\n{\n    uint8_t list[8];\n    uint8_t n;\n    uint8_t i;\n    uint8_t found = 0U;\n\n    SYS_I2C_Init(SYS_I2C_1, 400000U);      /* OLED 支持 400kHz */\n    n = SYS_I2C_Scan(SYS_I2C_1, list, 8U);\n    printf(\"[OLED] I2C1 scan: %u device(s)\\r\\n\", (unsigned)n);\n    for (i = 0U; i < n; i++) {\n        printf(\"       0x%02X\\r\\n\", list[i]);\n        if (list[i] == 0x3CU || list[i] == 0x3DU) found = 1U;\n    }\n    if (!found) {\n        printf(\"[OLED] 0x3C 不在总线上：查四根线 / 上拉 / 供电\\r\\n\");\n        return 1U;\n    }\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3CU) != SYS_I2C_OK) {\n        printf(\"[OLED] %s\\r\\n\", SYS_I2C_ErrStr(SYS_I2C_ERR_ADDR));\n        return 1U;\n    }\n    return 0U;\n}\n\n/* ---------------- 三、初始化 ---------------- */\nstatic uint8_t oled_setup(void)\n{\n    if (oled_probe() != 0U) return 1U;\n\n    /* OLED_Init() 内部已经按源码里的序列发完所有指令，\n     * 并且自带 ClearBuffer + Refresh 清成一屏全黑，最后 0xAF 开显示。\n     * 上电初始化阶段调度器还没跑，SYS_I2C_Lock 是空操作，安全。 */\n    OLED_Init();\n\n    if (OLED_IsOnline() == 0U) {\n        printf(\"[OLED] 寻址不到设备\\r\\n\");\n        return 1U;\n    }\n    OLED_ErrClear();\n    if (OLED_Refresh() != 0U) {\n        /* 能寻址但写不进去：上拉不足 / 走线过长 / 地址错。\n         * IsOnline 在这类场合仍会返回 1，必须看 Refresh 的返回值和 ErrCount。 */\n        printf(\"[OLED] 首屏刷新失败，LastErr=%u ErrCnt=%u\\r\\n\",\n               (unsigned)OLED_LastErr(), (unsigned)OLED_ErrCount());\n        return 1U;\n    }\n    printf(\"[OLED] init ok, addr=0x3C\\r\\n\");\n    return 0U;\n}\n\n/* ---------------- 四、位序自检：画一个点 ---------------- */\nstatic void oled_bitselfcheck(void)\n{\n    uint8_t b0, b7;\n\n    OLED_ClearBuffer();\n    OLED_DrawPoint(0U, 0U, 1U);            /* (0,0) → 第 0 页第 0 列 bit0 */\n    OLED_DrawPoint(0U, 7U, 1U);            /* (0,7) → 同字节 bit7 */\n    b0 = OLED_GetPoint(0U, 0U);\n    b7 = OLED_GetPoint(0U, 7U);\n    OLED_ShowString(0U, 0U, \"bit selfcheck\", 0U);\n    OLED_ShowString(0U, 16U, (b0 && b7) ? \"PASS\" : \"FAIL\", 0U);\n    (void)OLED_Refresh();\n\n    /* 板上应当看到：左上角一个亮像素，再往下 7 像素处另一个亮像素。\n     * 扩展实验：OLED_DrawPoint(1U, 0U, 1U) 之后，那一列若出现在 x=127，\n     * 说明整块屏被镜像了，那是 0xA1/0xC8 段重映射与扫描方向的问题。 */\n}\n\n/* ---------------- 五、文字与数字 ---------------- */\nstatic void oled_text_demo(const SysEnv_t *e)\n{\n    OLED_ClearBuffer();\n    OLED_ShowStringCenter(0U, \"ENV MONITOR\", 0U);\n    OLED_ShowString(0U, 16U, PANEL_LINE, 0U);\n\n    /* 定长对齐的关键：把所有变长字段都转成「固定宽度 + 前导空格」的字符串，\n     * 再整串刷上去，位置才不会跟着数值位数跳。 */\n    snprintf(s_line_last[0], sizeof(s_line_last[0]),\n             \"T: %6.2f C  \", (double)e->temp_c);\n    snprintf(s_line_last[1], sizeof(s_line_last[1]),\n             \"H: %6.2f %%  \", (double)e->humi_rh);\n    snprintf(s_line_last[2], sizeof(s_line_last[2]),\n             \"P: %7.1f hPa\", (double)e->press_hpa);\n    snprintf(s_line_last[3], sizeof(s_line_last[3]),\n             \"L: %5u lx  \", (unsigned)e->light_lx);\n\n    OLED_ShowString(0U, 24U, s_line_last[0], 0U);\n    OLED_ShowString(0U, 32U, s_line_last[1], 0U);\n    OLED_ShowString(0U, 40U, s_line_last[2], 0U);\n    OLED_ShowString(0U, 48U, s_line_last[3], 0U);\n\n    /* 不用浮点时的定点显示（板2）：OLED_ShowFixed(x, y, val, frac, int_len, inv)\n     * 例：温度 25.3℃ → val=253, frac=1 显示成 25.3。整数部分左对齐，\n     *     要「原地稳定」得自己补空格，见上面 snprintf 的做法。 */\n}\n\n/* ---------------- 六、图元与进度条 ---------------- */\nstatic void oled_ui_demo(const SysEnv_t *e)\n{\n    uint16_t permille;\n    float lx = (float)e->light_lx;\n\n    OLED_DrawRect(0U, 54U, 127U, 63U, 1U);\n    OLED_FillRect(2U, 56U, 12U, 61U, 1U);\n    OLED_DrawLine(14U, 56U, 40U, 61U, 1U);\n    OLED_DrawCircle(52, 58, 4, 1U);\n    OLED_DrawCircle(64, 58, 4, 1U);\n    OLED_DrawHLine(72U, 126U, 58U, 1U);\n\n    /* 进度条按千分比填充，内部自己 clamp 到 0~1000。\n     * 光照按 0~2000lx 映射到 0~1000（超量程截顶）。 */\n    permille = (uint16_t)((lx * 1000.0f) / 2000.0f);\n    OLED_ShowProgress(0U, 44U, 128U, 8U, permille);\n}\n\n/* ---------------- 七、整帧刷新：一次持锁包住 40 次事务 ---------------- */\nstatic uint8_t oled_frame_flush(const SysEnv_t *e)\n{\n    uint8_t fail;\n\n    /* 核心：把「改显存」和「推屏」整段括起来。\n     *   OLED_Refresh 内部是 8 页 × (1 次定位 + 4 块数据) = 40 次独立 I2C 事务，\n     *   若 MPU6050 / 24C02 的事务插进这 40 次之间，同一帧就会被写坏，\n     *   屏上表现为「一半新一半旧的横向撕裂条」。\n     *   这里的 Lock 是 SYS_I2C 的每总线递归互斥量：同一任务重复 Lock 只是计数 +1，\n     *   不会自锁死，所以内层 OLED_Refresh 自己再取一次锁完全安全。\n     *   代价：整帧约 23~25ms 内，总线上其他从机的读事务要排队等 20ms 级，\n     *   这是「整帧不可插入」的必然代价，不是 bug。 */\n    SYS_I2C_Lock(SYS_I2C_1);\n    oled_text_demo(e);\n    oled_ui_demo(e);\n    fail = OLED_Refresh();\n    SYS_I2C_Unlock(SYS_I2C_1);\n\n    return fail;\n}\n\n/* 脏页刷新：只把「变化的那几页」重推上去，省掉大部分总线时间。\n * 一页 = 竖直 8 像素 = 一行 8×16 文字的上半或下半，所以按行分页判断即可。 */\nstatic uint8_t oled_flush_dirty_pages(const char line[4][24], const uint8_t *dirty)\n{\n    uint8_t page;\n    uint8_t fail = 0U;\n\n    SYS_I2C_Lock(SYS_I2C_1);\n    for (page = 0U; page < 4U; page++) {\n        if (dirty[page] == 0U) continue;\n        (void)line;   /* 本驱动按页整体推屏：改完显存后逐页定位重发 */\n    }\n    /* 说明：本项目 oled.c 只提供「整帧 Refresh」，要做真正的脏页刷新，\n     * 需要仿照 OLED_Refresh 的逐页写法，给源码加一个 OLED_RefreshPage(page)；\n     * 那是换算法不换硬件，改完立刻能看到刷屏时间从 23ms 掉到 3ms 量级。 */\n    SYS_I2C_Unlock(SYS_I2C_1);\n\n    return fail;\n}\n\n/* ---------------- 八、FreeRTOS 显示任务 ---------------- */\nstatic void vTaskOled(void *pv)\n{\n    SysEnv_t e;\n    uint8_t dirty[4];\n\n    (void)pv;\n    memset(&e, 0, sizeof(e));\n\n    if (oled_setup() != 0U) {\n        printf(\"[OLED] 初始化失败，显示任务退出（通讯部分继续跑）\\r\\n\");\n        vTaskDelete(NULL);\n        return;\n    }\n\n    oled_bitselfcheck();        /* 上电先自检一次位序，人眼可判 */\n    vTaskDelay(pdMS_TO_TICKS(1000));\n\n    for (;;) {\n        if (xQueueReceive(s_env_q, &e, pdMS_TO_TICKS(500)) == pdPASS) {\n            /* 拿最新一帧：若队列里还压着旧数据，全部丢掉只留最后一条，\n             * 屏上要的是「现在」，不是「历史」。 */\n            SysEnv_t newer;\n            while (xQueueReceive(s_env_q, &newer, 0) == pdPASS) e = newer;\n            dirty[0] = 1U;\n        }\n\n        /* 限速：人眼 5Hz 足够，也给 I2C 总线留出给传感器的空档 */\n        if ((xTaskGetTickCount() - s_oled_tick_last) < pdMS_TO_TICKS(200)) {\n            vTaskDelay(pdMS_TO_TICKS(20));\n            continue;\n        }\n        s_oled_tick_last = xTaskGetTickCount();\n\n        if (e.online == 0U) {\n            OLED_ClearBuffer();\n            OLED_ShowStringCenter(0U, \"SENSOR OFFLINE\", 0U);\n            OLED_ShowStringCenter(16U, \"check wiring\", 0U);\n            /* 反显：黑底白字 ↔ 白底黑字，用来做报警高亮 */\n            OLED_ShowStringCenter(32U, \"ALARM\", 1U);\n            (void)OLED_Refresh();\n            vTaskDelay(pdMS_TO_TICKS(500));\n            continue;\n        }\n\n        if (oled_frame_flush(&e) == 0U) {\n            s_oled_refresh_ok++;\n        } else {\n            s_oled_refresh_bad++;\n            /* 写不进去就降级：放慢到 2 秒一次，避免每次重试 3 遍 + I2C 超时\n             * 把 20ms 级的刷屏放大到数百毫秒，拖垮整个显示任务。 */\n            vTaskDelay(pdMS_TO_TICKS(2000));\n        }\n        vTaskDelay(pdMS_TO_TICKS(20));\n    }\n}\n\n/* ---------------- 九、采集端：往队列里塞数据（与显示解耦） ---------------- */\nstatic void vTaskEnv(void *pv)\n{\n    SysEnv_t e;\n\n    (void)pv;\n    for (;;) {\n        e.temp_c    = 25.3f;\n        e.humi_rh   = 61.8f;\n        e.press_hpa = 1013.2f;\n        e.light_lx  = 420U;\n        e.mpu_ax    = 12;\n        e.online    = 1U;\n\n        /* 队列长度 4：显示任务偶尔被刷屏占住 23ms，采集不该因此丢数据；\n         * 满了就直接覆盖旧的（xQueueOverwrite 语义用长度 1 的队列实现）。 */\n        (void)xQueueSend(s_env_q, &e, 0);\n        vTaskDelay(pdMS_TO_TICKS(100));\n    }\n}\n\n/* ---------------- 十、创建任务 ---------------- */\nvoid app_oled_start(void)\n{\n    s_env_q = xQueueCreate(4U, sizeof(SysEnv_t));\n    if (s_env_q == NULL) return;\n\n    /* 栈给足：snprintf 里带浮点格式化，吃栈；优先级低于采集与控制任务，\n     * 刷屏是「慢活」，绝不能挡着急着跑的控制回路。 */\n    (void)xTaskCreate(vTaskOled, \"OLED\", 512U, NULL, 2U, NULL);\n    (void)xTaskCreate(vTaskEnv,  \"ENV\",  256U, NULL, 3U, NULL);\n}\n\n/* ============================================================\n *  板1 的对应接口（名字与参数都不同，用同一块屏但要改这一层）\n * ------------------------------------------------------------\n *  SYS_OLED_Init(bus, addr)      两参数，自己内部 SYS_I2C_Init(bus, 400000)\n *  SYS_OLED_Clear()              只清显存\n *  SYS_OLED_Refresh()            整帧 1024 字节一次流水发出（水平寻址模式）\n *  SYS_OLED_ShowChar(page, x, ch)       page = 页号 0~7，不是像素行\n *  SYS_OLED_ShowString(page, x, str)    到右边界停住，不自动换行\n *  SYS_OLED_ShowNum(page, x, int32)     无 inv、无定宽\n *  SYS_OLED_ShowFloat(page, x, v, dec)  有专用浮点函数\n *  SYS_OLED_SetPixel(x, y, on)\n *  SYS_OLED_ShowBitmap(page, x, bmp, w, h)\n *  板1 没有 DrawLine / DrawRect / DrawCircle / ShowProgress，画图元只能用 SetPixel。\n * ============================================================ */",
 f:[
  [
   "先确认总线上有没有它：SYS_I2C_Scan 抓 0x3C",
   "拿到一块 OLED，第一件事并非写初始化，而是确认一个更基本的问题：MCU 能否与它通信。I2C 是「主问从答」的总线，从机插着但线没接好、上拉缺失、供电没到，症状全都长得一样，屏不亮。而屏不亮既可能是通讯问题，也可能是屏本身、对比度、供电问题。所以必须先把「通讯」和「显示」拆开验证，否则后面所有调试都是盲猜。\n\n本项目板2 的 I2C1 上已经挂了两个从机：24C02（0x50）和 MPU6050（0x68），OLED（0x3C）是第三个。这正是「共享总线」的典型场景，也让第一步的扫描特别有价值，它一次性告诉三件事：总线能不能动、总线上有谁、OLED 的地址到底是 0x3C 还是 0x3D。\n\n地址这个问题要单独说。 SSD1306 的 7 位地址由 SA0 引脚决定：SA0 接地是 0x3C，接 VCC 是 0x3D。很多模块背面丝印印的是 0x78 / 0x7A，那是含读写位的 8 位地址（0x3C<<1=0x78，0x3D<<1=0x7A）。SYS_I2C 这一层要的是 7 位地址，直接右移一位，写 0x3C。写 0x78 的后果是地址错一位，从机全程不应答，现象是「扫不到任何东西」或「扫到一堆假地址」。",
   "① 接好四根线：VCC→3.3V、GND→GND、SCL→PB8、SDA→PB9。模块板载电荷泵，3.3V 直接可用，不要接 5V。\n② 先 SYS_I2C_Init(SYS_I2C_1, 400000) 把总线开起来（OLED 支持 400kHz）。\n③ 调 SYS_I2C_Scan(SYS_I2C_1, list, 8)，把扫到的地址全部 printf 出来。\n④ 在列表里找 0x3C（或 0x3D）。找到才是「器件在总线上」。\n⑤ 再补一道 SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3C) 确认单点应答。",
   "static uint8_t oled_probe(void)\n{\n    uint8_t list[8];\n    uint8_t n;\n    uint8_t i;\n    uint8_t found = 0U;\n\n    /* OLED 支持 400kHz；本板 I2C1 = PB8(SCL) / PB9(SDA) */\n    SYS_I2C_Init(SYS_I2C_1, 400000U);\n\n    /* 扫描 0x08~0x77，把总线上所有从机打印出来，\n     * 这一步同时能看到 24C02(0x50) 和 MPU6050(0x68) 在不在，\n     * 总线整体健不健康一眼就知道。 */\n    n = SYS_I2C_Scan(SYS_I2C_1, list, 8U);\n    printf(\"[OLED] I2C1 scan: %u device(s)\\r\\n\", (unsigned)n);\n    for (i = 0U; i < n; i++) {\n        printf(\"       0x%02X\\r\\n\", list[i]);\n        if (list[i] == 0x3CU || list[i] == 0x3DU) found = 1U;\n    }\n\n    if (!found) {\n        /* 扫不到：四根线 / 上拉 / 供电，按顺序排 */\n        printf(\"[OLED] 0x3C 不在总线上：查四根线 / 上拉 / 供电\\r\\n\");\n        return 1U;\n    }\n\n    /* 单点再确认一次，练一下 ErrStr：无应答时它会指出卡在哪一步 */\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3CU) != SYS_I2C_OK) {\n        printf(\"[OLED] %s\\r\\n\", SYS_I2C_ErrStr(SYS_I2C_ERR_ADDR));\n        return 1U;\n    }\n    return 0U;\n}",
   "串口打印里出现 `0x3C`，并且 SYS_I2C_IsDeviceReady 返回 SYS_I2C_OK(0)。\n判断标准很干脆：只要 0x3C 出现在扫描结果里，通讯这道门就过了，屏还不亮也跟接线无关，问题一定在后面的初始化或刷屏。反之，扫不到 0x3C 时不要急着改代码，先量电压、查上拉、对调 SDA/SCL。",
   "地址写 0x3C（7 位），不要写 0x78（8 位左移）。这是 I2C 驱动最常见的头号错误，且现象隐蔽：有些库内部会再左移一次，于是 0x3C 又变回 0x78 碰巧能通，换个库就全废。\n上拉缺失的典型表现：能扫到地址，但刷新不稳，时亮时不亮、偶尔花屏。板载 I2C1 已有 4.7k 上拉（给 24C02/MPU6050 用的），把模块插到 I2C 排针上就共享了；若从排针另引长线出去，长线的分布电容会把上升沿拖慢，必须确认模块自带或另加 4.7k 上拉到 3.3V。\n别忘 SYS_I2C_Init(bus, 400000)：不初始化就用，SPL 的 I2C 外设还没使能，所有事务直接失败，而扫描会返回 0，看起来像「屏没插」，是总线压根没开。\n模块 TXD/RXD 那套不适用：OLED 是 I2C，没有交叉接线问题，但 SDA/SCL 接反了同样扫不到，接反是「扫不到 0x3C」的第二大原因。\n扫到 0x3C 但 IsDeviceReady 报 SYS_I2C_ERR_TIMEOUT 时，别反复重试，先调 SYS_I2C_BusReset(SYS_I2C_1)：从机把 SCL 拉死是长线环境的偶发现象。",
   "⑧ I2C 总线 · SYS_I2C_Scan · SYS_I2C_Init · SYS_I2C_IsDeviceReady · SYS_I2C_ErrStr · SYS_I2C_BusReset · SYS_I2C_ADDR_SSD1306"
  ],
  [
   "吃透控制字节与页寻址：为什么「能扫到却什么都不变」",
   "这一步是整个 OLED 学习里最抽象、也最容易卡住的地方，必须讲透。\n\n第一件事：控制字节（control byte）。 SSD1306 挂在 I2C 上，但它不会区分「命令」和「数据」，因为它根本不知道在发什么。协议规定：每一笔 I2C 事务的第一个数据字节是控制字节，`0x00` 表示后面跟的全是命令，`0x40` 表示后面跟的全是显存数据。这是初学者第一个大问题：把命令和数据混在一笔事务里发，或者控制字节写错，SSD1306 就会把参数当成显存内容写进去、把显存数据当成命令。现象非常典型：能扫到地址、I2C 也没有报错、但屏上什么都不变。\n\n本项目的两套驱动都把这层处理得干干净净：板2 的 `oled_wr(ctrl, buf, len)` 把 0x00/0x40 当成 sys_i2c 的「寄存器号」传给 SYS_I2C_WriteBytes，刚好等价，这是绝大多数 OLED 驱动的通用写法；板1 用 OLED_CTRL_CMD / OLED_CTRL_DATA 两个宏。\n\n第二件事：页寻址（page addressing）。 128×64 的屏 = 128 列 × 8 页，每页竖直 8 个像素，共 128×8 = 1024 字节显存。关键在于显存按「页」而非「行」组织：一个显存字节同时管竖直方向的 8 个像素。像素 (x,y) 落在哪个字节的哪一位？\n\n    oled_buf[(y / 8) * 128 + x]  的第 (y % 8) 位\n\n而且 bit0 在这 8 个像素的最上面（低位在上）。所以想让 (0,0) 亮，要写第 0 页第 0 字节的 bit0；想让 (0,7) 亮，是同一个字节的 bit7。理解不了这一层，就会写出「画一个点结果竖着亮出 8 个点」这种问题。\n\n为什么要有页这一层？ 因为它和 OLED 面板的物理结构一致：SSD1306 内部有 8 个 COM 驱动组，一次移位输出就是一整页。所以驱动可以直接把显存整块搬过去，不需要任何格式转换，这也是「先画到显存、最后一次推屏」这种架构能又快又不闪的根本原因。\n\n最后是两种寻址模式的选择，本项目两板恰好各用一种：板2 发 0x20,0x00 选页模式，刷屏时每页先发页地址+列地址（0xB0|page、0x00、0x10）再连写 128 字节；板1 发 0x20,0x00 之后用的是水平模式那套窗口命令（0x21 设列窗口、0x22 设页窗口），一次事务把 1024 字节流水发完。模式与刷屏写法必须配套，这是第 3 步 `0x20,0x00` 那条命令的全部意义。",
   "① 打开 oled.c，找到低层 oled_wr，确认它把 ctrl 当「寄存器号」传给 SYS_I2C_WriteBytes。\n② 数清显存大小：OLED_PAGE_CNT × OLED_WIDTH = 8 × 128 = 1024 字节。\n③ 写出映射公式并对照源码：显存索引 (y>>3)*OLED_WIDTH + x，位号 (y & 0x07)。\n④ 确认位序：bit0 = 页内最上面那一行（板2 注释原话是 buf[p][c] 的 bit0 = 该页第 0 行像素）。\n⑤ 查清自己所看的那套驱动用哪种寻址模式：板2 逐页写=页模式，板1 整帧流水=水平模式。",
   "/* ---- 控制字节：一笔事务的第一个数据字节 ----\n *   [从机地址+W] [0x00] [命令字节...]     ← 0x00 = 后面是命令\n *   [从机地址+W] [0x40] [显存数据...]     ← 0x40 = 后面是显存数据\n *\n * 板2 oled.c 的做法：把 0x00/0x40 当作 sys_i2c 的「寄存器号」\n */\n#define OLED_CTRL_CMD   0x00U\n#define OLED_CTRL_DATA  0x40U\n\n/* ---- 显存布局：128 列 × 8 页 = 1024 字节 ---- */\n#define OLED_W   128U\n#define OLED_H   64U\n#define OLED_P   8U              /* 8 页，每页竖直 8 像素 */\n\n/* ---- 像素 (x,y) → 显存字节 + 位号 ----\n *   字节 = (y / 8) * 128 + x\n *   位号 = y % 8，其中 bit0 在这一页的最上面\n */\n#define OLED_IDX_PUB(x, y)   ((((y) >> 3) * OLED_W) + (x))\n#define OLED_BIT_PUB(y)      (1U << ((y) & 0x07U))\n\n/* 画点的实质（板2 源码 OLED_DrawPoint 里就是这两行）：\n *    亮：oled_buf[y >> 3][x] |=  (uint8_t)(1U << (y & 0x07U));\n *    灭：oled_buf[y >> 3][x] &= (uint8_t)~(1U << (y & 0x07U));\n * 越界（x>=128 或 y>=64）直接忽略，不报错，所以画图元时\n * 计算出的坐标溢出不会崩，但会「画不出来」，要留意。 */\n\n/* ---- 开域：先清成整屏黑 ----\n * 做个反例对照：把 OLED_CTRL_CMD 故意写成 0x40（那是数据），\n * 屏上不会有任何反应，I2C 也不报错，这就是「能扫到却什么都不变」。\n */\nstatic void oled_ctrlbyte_demo(void)\n{\n    OLED_ClearBuffer();                 /* 只清 RAM，1024 字节归零 */\n    OLED_ShowString(0U, 0U, \"ctrl byte &page\", 0U);\n    OLED_ShowString(0U, 16U, \"0x00=CMD 0x40=DATA\", 0U);\n    OLED_ShowString(0U, 32U, \"buf[(y/8)*128+x]\", 0U);\n    OLED_ShowString(0U, 48U, \"bit = y%8, bit0 top\", 0U);\n    (void)OLED_Refresh();               /* 唯一的「真正显示」动作 */\n}",
   "文本能正确出现在四行上，且字形是正的、不是竖着拉长的乱码，字形正常就说明「哪个字节的哪一位对应哪个像素」这套映射是对的。\n再做一个更硬的验证：用 OLED_GetPoint(0,0) 和 OLED_GetPoint(0,7) 读回来，看是不是都返回 1（前提是已经画过这两个点，见第 4 步）。\n如果屏上出现「竖着拉长的花字」，那是位序方向错了（把 bit0 当成底部），要回头查字库取模方向。",
   "控制字节混用是最阴的问题：I2C 全程不报错、地址能扫到、返回值全是 OK，屏就是不变。遇到这种「一切正常但没反应」，第一个要怀疑的就是 0x00/0x40 有没有写对、有没有把命令和数据塞进同一笔事务。\n一个字节管竖直 8 个像素，别按「一个字节一行」去想。想画一条水平线，必须逐列去改不同字节的同一个位；想画一条垂直线，才是改同一个字节的多个位。\n位序搞反（bit0 当底部）不会报错，只会让所有图形上下镜像、字库变成花字，非常容易误判成「字库错了」。\n别一画完就以为屏上会有：所有 OLED_DrawXxx / OLED_ShowXxx 只改 RAM，没有 OLED_Refresh() 就永远不变。这是第二大疑问（「我代码明明执行了」）。\n页模式下写显存不能跨页：SSD1306 在页模式里写完一页的最后一列会自动回到本页第 0 列（而不是进下一页），所以一页必须发一次页地址；板1 的水平模式没这个问题，一次 1024 字节自动跨页铺满，模式不同，问题也不同。",
   "㉓ 本卡的第 3 步 · ㉓ 本卡的第 4 步 · SYS_I2C_WriteBytes · 板2 oled.c 的 oled_wr / OLED_Refresh · 板1 sys_oled.c 的 oled_cmd / oled_init_seq"
  ],
  [
   "照源码写初始化序列，把屏点亮",
   "初始化序列有两类错误：抄错参数和漏掉关键命令。这两类都很隐蔽，所以这一步的纪律是：照本项目源码逐条抄，别凭 SSD1306 手册自由发挥。手册里同一组命令在不同版本手册、不同模块上默认值都不一样，凭印象写出来的表往往点不亮。\n\n整个上电流程的设计意图是这样的：\n\n① 先关显示再配置。 第一条 0xAE 把显示关掉。因为配置过程中寄存器是一位一位改的，中途总会出现「参数不完整」的瞬间状态，屏上就会闪一下花屏。先关、配完再开，屏上从头到尾只有干净的最终画面。\n\n② 电荷泵必须开（0x8D, 0x14）。 这一条是「屏完全不亮」的头号嫌疑犯。SSD1306 的 OLED 面板需要约 7~9V 的驱动电压，模块上没有外部升压电路，全靠芯片内部电荷泵产生。0x14 是「使能内部升压」的魔法值。忘发这一条，现象很干净：I2C 一切正常、ErrCount 为 0、屏就是不亮。很多人在这里卡几个小时，跑去查接线和地址，就差这一条。\n\n③ 显示时钟分频、复用率、显示偏移、起始行，这四个参数决定了「画多少行、从哪里开始画」。本项目两板都是 0xD5,0x80（时钟）、0xA8,0x3F（复用率 64 行，128×32 的屏要改成 0x1F）、0xD3,0x00（偏移 0）、0x40（起始行 0）。\n\n④ 方向类命令：0xA1（段重映射）与 0xC8（扫描方向）。 这两个一起决定「屏的物理左上角」在哪。改错不会坏，只会镜像/翻转，所以它们是调试方向问题时唯二的两个开关：把 0xA1 换成 0xA0 左右就翻过来，把 0xC8 换成 0xC0 上下就翻过来。0xDA,0x12 是 COM 引脚配置（64 行屏的标准值，交替行 + 不左右反转）。\n\n⑤ 亮度、预充电、VCOMH。 0x81,0xCF 是对比度；0xD9,0xF1 是预充电周期；0xDB,0x40 是 VCOMH 电压。这三个共同决定「看起来亮不亮、匀不匀」。本项目两板源码里对比度都是 0xCF，不是手册常见的 0x7F；0x7F 能用但偏暗，别被别的教程带跑。\n\n⑥ 显示行为：0xA4 跟随显存、0xA6 正常显示、0x2E 关滚动。 0xA4 和 0xA5 的区别是「显示显存内容」还是「全屏点亮」（后者是老化测试用的）；0xA6/0xA7 是正常/整体反色；0x2E 停掉出厂可能开着的滚动效果。\n\n⑦ 清屏 + 开显示。 板2 的顺序是：ClearBuffer 清 RAM → Refresh 推一屏全黑 → 0xAF 开显示。这个顺序保证开显示的那一刻屏上已经是干净的。板2 还特意忽略了首次 Refresh 的返回值，屏可能后插上，不该让 Init 因此失败。",
   "① 打开 oled.c（板2）或 sys_oled.c（板1），把初始化序列整段抄进自己的工程。\n② 检查每条命令：0xAE 关 → 0xD5/A8/D3/40 → 0x8D,0x14 电荷泵 → 0x20,0x00 寻址模式 → 0xA1/C8 → 0xDA,0x12 → 0x81,0xCF → 0xD9,0xF1 → 0xDB,0x40 → 0xA4/A6/2E → 清屏 Refresh → 0xAF 开。\n③ 确认电荷泵那条（0x8D, 0x14）在，且参数是 0x14 不是 0x10。\n④ 调 OLED_Init()（板2）或 SYS_OLED_Init(bus, addr)（板1），再 OLED_Refresh() 一次推全黑。\n⑤ 出错时用 OLED_IsOnline() / OLED_ErrCount() / OLED_LastErr() 三个观测点定位。",
   "/* ---- 板2 初始化序列（源码 oled.c 逐条，照搬） ----\n * 每条后面括号是 oled.c 里的原注释含义。\n */\nstatic void oled_init_seq_demo(void)\n{\n    OLED_Init();        /* 内部完整序列，展开就是下面这一串： */\n}\n\n/*  0xAE              关显示（配置期间先关，避免花屏）\n *  0xD5, 0x80        显示时钟分频/振荡频率\n *  0xA8, 0x3F        复用率 = 64 行（0x3F = 63；128x32 屏改 0x1F）\n *  0xD3, 0x00        显示偏移 = 0\n *  0x40              显示起始行 = 0\n *  0x8D, 0x14        电荷泵：0x14 = 内部升压使能（必须。忘发=屏永不亮）\n *  0x20, 0x00        寻址模式 = 页模式（配合板2 逐页刷新的写法）\n *  0xA1              段重映射：列 127 → SEG0（左右方向）\n *  0xC8              行扫描方向：从下往上（上下方向）\n *  0xDA, 0x12        COM 引脚配置：交替 + 不左右反转（64 行屏）\n *  0x81, 0xCF        亮度（0x00~0xFF）源码用 0xCF\n *  0xD9, 0xF1        预充电周期\n *  0xDB, 0x40        VCOMH 电压\n *  0xA4              显示跟随显存内容（不是全亮）\n *  0xA6              正常显示（非反色；0xA7 = 整体反色）\n *  0x2E              关闭滚动\n *  ---- 然后 ----\n *  ClearBuffer()     清 1024 字节显存\n *  OLED_Refresh()    推一屏全黑（板2 忽略返回值：屏可能后插上）\n *  0xAF              开显示\n */\n\n/* 自己点亮的完整包装：先探总线，再初始化，再验证刷屏 */\nstatic uint8_t oled_setup(void)\n{\n    if (oled_probe() != 0U) return 1U;   /* 第 1 步的探测函数 */\n\n    OLED_Init();\n\n    if (OLED_IsOnline() == 0U) {\n        printf(\"[OLED] 寻址不到设备\\r\\n\");\n        return 1U;\n    }\n    OLED_ErrClear();                    /* 排查前先清零统计 */\n    if (OLED_Refresh() != 0U) {\n        /* 能寻址但写不进去：上拉不足 / 走线过长 / 地址错。\n         * IsOnline 在这类场合仍返回 1，必须看 Refresh 返回值。 */\n        printf(\"[OLED] 首屏刷新失败，LastErr=%u ErrCnt=%u\\r\\n\",\n               (unsigned)OLED_LastErr(), (unsigned)OLED_ErrCount());\n        return 1U;\n    }\n    printf(\"[OLED] init ok, addr=0x3C\\r\\n\");\n    return 0U;\n}",
   "OLED_Init() 执行完之后：① 屏上整片干净的黑（没有残留雪花点、没有半屏乱码）；② OLED_IsOnline() 返回 1；③ OLED_Refresh() 返回 0（0 表示 8 页全部写成功）；④ OLED_ErrCount() 自 ErrClear 之后保持 0。\n四个条件全过，屏就算「点亮了」。此时屏是黑的，黑屏就是成功，因为显存刚被清空，这一步本来就不该有内容。",
   "漏发电荷泵（0x8D,0x14）是「I2C 一切正常但屏全黑」的第一原因，而且不报任何错。排查顺序永远是：先看这一条发了没有。\n对比度不要照搬其他教程：本项目两板源码均用 0x81,0xCF。改小到 0x7F 只是变暗，但如果在昏暗环境里调试，很容易误判成「屏坏了」。\n0xA5 是全屏点亮（老化测试用），不是「开显示」。真正的开显示是 0xAF。这两个混淆会出现「灯全亮但什么都不显示」的壮观场面。\n板1（sys_oled.c）的 Init 是两参数 SYS_OLED_Init(bus, addr)，返回 0 才是成功、1 是无应答，和板2 的 void OLED_Init() 完全不同；板1 内部还会自己调 SYS_I2C_Init(bus, 400000) 和 SYS_I2C_IsDeviceReady，所以板1 不需要先开总线。若总线上还有只认 100kHz 的老器件，初始化完后可以再 SYS_I2C_Init(bus, 100000) 降回来（OLED 仍可用）。\n复用率 0xA8 必须和屏的实际行数匹配：128×32 的屏写 0x3F 就会出现「只显示一半、另一半错位」。\n初始化阶段能加锁是因为那时调度器还没启动、SYS_I2C_Lock 是空操作；如果把 OLED_Init 放进某个任务里做迟到的热插拔初始化，就必须自己保证它不在刷屏的临界区里被并发调用。",
   "⑧ I2C 总线 · ㉓ 本卡的第 1 步 · ㉓ 本卡的第 8 步 · 板2 OLED_Init · 板1 SYS_OLED_Init · SYS_I2C_Lock · SYS_I2C_Unlock"
  ],
  [
   "画一个点，实测显存位序",
   "这一步看似简单，但它是整套绘图的地基：如果 (x,y) 到「哪个字节的哪一位」的映射错了，后面画的线、矩形、圆、字符会全部跟着错，而且错得很有迷惑性，线条看着像线、字看着像字，只是位置和形状微妙地不对，很容易被当成「算法问题」而不是「位序问题」。\n\n这里要用一个可预测的实验确定位序，而非「验证屏能画」。最干净的实验是画两个点：`OLED_DrawPoint(0,0,1)` 和 `OLED_DrawPoint(0,7,1)`。为什么选这两个？因为 (0,0) 和 (0,7) 落在同一个显存字节（第 0 页第 0 列），但分别是最低位和最高位。\n\n按源码的映射：\n\n    oled_buf[(y >> 3) * 128 + x] 的第 (y & 7) 位\n    (0,0) → oled_buf[0] 的 bit0\n    (0,7) → oled_buf[0] 的 bit7\n\n画完两个点，`oled_buf[0]` 应该正好等于 0x81（bit0 和 bit7 置位）。这是一个可以用眼睛、也可以用调试器/串口直接验的强判据：\n\n- 屏上看到左上角一个亮像素、紧挨着往下第 8 个像素处另一个亮像素，且中间 6 个点是暗的 → 位序正确、页内方向正确。\n- 两个点上下贴在一起（同一个像素附近）→ 说明 `y>>3` 和 `y&7` 用反了。\n- 两个点水平方向相隔很远 → 说明算索引时把 x 和 page 乘错了（写成 x*8+page 之类）。\n- 一个点亮右侧很远、另一个在最左 → 段重映射方向反了，回头查 0xA1/0xA0。\n\n为什么值得专门花一步？因为这个判据是二值的、可复现的，而且一次就把「页内位序」和「页间排布」两个维度同时覆盖了。以后再遇到图形位置不对，已经有一个「地基是对的」的结论可以依赖，只需要往上查算法。",
   "① 先 OLED_ClearBuffer() 把显存清干净（别在旧内容上做实验）。\n② OLED_DrawPoint(0, 0, 1)，再 OLED_DrawPoint(0, 7, 1)，只画这两个点。\n③ 用 OLED_GetPoint(0,0) 和 OLED_GetPoint(0,7) 把显存读回来，确认都是 1。\n④ 加一行文字，再做 OLED_Refresh() 推屏。\n⑤ 眼睛对着屏看，按上面那四条对照表判断位序对不对。\n⑥ （可选硬核验证）在调试器里看 oled_buf[0]，应当等于 0x81。\n⑦ （方向实验）把 0xA1 改 0xA0、0xC8 改 0xC0，各看一次镜像效果，这两个开关。",
   "static void oled_bitselfcheck(void)\n{\n    uint8_t b0, b7;\n\n    OLED_ClearBuffer();\n\n    /* (0,0) 和 (0,7) 落在同一个显存字节 oled_buf[0]：\n     *   (0,0) → bit0        (0,7) → bit7\n     * 画完这两个点，oled_buf[0] 应当正好是 0x81。 */\n    OLED_DrawPoint(0U, 0U, 1U);\n    OLED_DrawPoint(0U, 7U, 1U);\n\n    /* 从显存读回来验一次，不依赖眼睛 */\n    b0 = OLED_GetPoint(0U, 0U);\n    b7 = OLED_GetPoint(0U, 7U);\n\n    OLED_ShowString(0U, 0U, \"bit selfcheck\", 0U);\n    OLED_ShowString(0U, 16U, (b0 && b7) ? \"PASS\" : \"FAIL\", 0U);\n\n    (void)OLED_Refresh();       /* 推屏后才看得见 */\n\n    /* 板上应当看到：左上角一个亮像素，再往下第 8 个像素处另一个亮像素，\n     * 中间 6 个点是暗的。\n     *\n     * 扩展实验（每条只改一个变量，看完就改回来）：\n     *   ① OLED_DrawPoint(1U, 0U, 1U)：亮像素若出现在 x=127，段重映射反了 → 查 0xA1；\n     *   ② 把两个点换成 (0,0) 和 (7,0)：亮像素若竖着排，说明位序当成了「一字节一行」。\n     */\n}",
   "屏上左上角出现一上一下两个亮像素，竖直间隔 7 个像素；串口/日志里 PASS；OLED_GetPoint(0,0)==1 且 OLED_GetPoint(0,7)==1。\n再补一个「读回来」的硬验证：调试器里看 oled_buf[0] == 0x81。\n这一步过了，就可以放心往上画线、画框、写文字，地基是对的。",
   "最隐蔽的错法是把 `y>>3` 和 `y&7` 用反（写成 buf[y&7][x]），前几个点看着「差不多对」，一画满屏就彻底错位。\n越界不报错：OLED_DrawPoint 在 x>=128 或 y>=64 时直接 return（板2 源码就是这么写的），所以算出负数坐标（无符号回绕成 65535）不会崩，只会静默画不出来。调试「图元某一段消失」时要先怀疑坐标越界。\n板1 用的是 `SYS_OLED_SetPixel(x, y, on)`，语义与板2 的 DrawPoint 相同，但板1 没有 GetPoint，想「读回来验证」在板1 上做不到，只能靠眼睛。这是两板接口不对等的一处，写跨板代码时要。\n别在没 ClearBuffer 的显存上做位序实验：旧内容的残留位会让「0x81」这个判据失效。\n想验证得更狠一点，可以一次画一条竖线 x=0, y=0..7（8 个点），oled_buf[0] 应当等于 0xFF，这是「一个字节管竖直 8 像素」最直观的证明。",
   "㉓ 本卡的第 2 步 · ㉓ 本卡的第 3 步 · 板2 OLED_DrawPoint / OLED_GetPoint · 板1 SYS_OLED_SetPixel · ⑧ I2C 总线"
  ],
  [
   "画线、矩形、圆与进度条",
   "有了正确的位序，图元就只是算法问题了，但在显存上画图元和「在纸上画图」有一个本质区别，值得讲清。\n\n区别一：所有图元最终都要落到「置位/清位」这一个操作上。 板2 的实现很典型，OLED_DrawLine 是 Bresenham，OLED_DrawRect 是四条 HLine/VLine，OLED_FillRect 是逐行 HLine，OLED_DrawCircle 是八分对称画八次点，OLED_ShowProgress 是先画外框再按比例填竖线。它们全部只调用 OLED_DrawPoint。这带来两个好处：越界处理只需要在唯一一个地方做一次（DrawPoint 里 return），以及每一层都能独立测试。\n\n区别二：画图元改的是显存里的位，而非「画上去」，所以有 on 参数。 板2 每个图元都有 `on` 参数（1 画、0 擦）。这不是可有可无的，不做全屏清的局部刷新，就是靠 `on=0` 把旧图形「擦掉」。理解这一点，才能理解为什么「局部刷新」可行：擦和画走同一套代码。\n\n区别三：所有图元的坐标是「闭区间」。 OLED_DrawHLine(x0, x1, y, on) 的 x0 和 x1 都会画，OLED_DrawRect(x0,y0,x1,y1,on) 画的是从 (x0,y0) 到 (x1,y1) 的四条边。所以矩形宽度是 `x1-x0+1`。写代码时忘记这个 +1，画出 127 宽而不是 128 宽的框，是很难发现的「差一像素」问题。\n\nBresenham 为什么在这里比「按斜率算浮点」好？ 因为它只用整数加减和比较，没有乘除、没有浮点、没有累积误差，而且天然均匀。F407 有 FPU，浮点也不慢，但在显存逐点写这种每像素一次函数调用的场景里，省掉的每次除法都是实打实的循环开销。板2 的 DrawLine 和 LCD 模块共用同一套 Bresenham，是为了复用与速度。\n\n进度条和柱状图用的是千分比（permille，0~1000）而不是百分比。源码里 `OLED_ShowProgress(x, y, w, h, permille)`：先画外框矩形，内部可用宽度是 `w-2`（去掉左右各 1 像素边框），填充宽度是 `(w-2) * permille / 1000`。用千分比是为了避免整数百分比在窄条上的量化误差（128 像素的条，1% 只有 1.28 像素）。它会自己把 permille 截到 1000 以内，超了不会画出去。\n\n图标/位图的取模格式也是同一套页模型：板1 的 `SYS_OLED_ShowBitmap(page, x, bmp, w, h)` 要求数据「按页、列排，先第 0 页 8 行逐列 1 字节，再第 1 页……每字节 bit0 在页顶」。取模软件的设置必须是「页模式/列行式、低位在上」。这个格式与显存格式一模一样，所以 ShowBitmap 可以整块搬运，不需要任何转换。",
   "① 先画只有 1 像素宽/高的线，确认端点位置（尤其确认闭合区间没算错）。\n② 画矩形框 DrawRect，再 FillRect 填充，看边框占了几像素、填充有没有盖住边框。\n③ 画圆：圆心 + 半径，看边缘有没有缺口、有没有明显不对称。\n④ 画进度条：传 0、500、1000 三个值，看空/半/满，以及外框是否完整。\n⑤ 两板差异：板2 有全套图元，板1 只有 SetPixel，板1 画线/框要自己写循环。",
   "/* ---- 板2 全套图元（源码 oled.c 里的实现要点） ---- */\nstatic void oled_ui_demo(const SysEnv_t *e)\n{\n    uint16_t permille;\n    float lx = (float)e->light_lx;\n\n    /* 外框：坐标是闭区间，(0,54)~(127,63) 正好贴住屏幕最后 10 行 */\n    OLED_DrawRect(0U, 54U, 127U, 63U, 1U);\n\n    /* 实心块：填出一个「图标」的感觉 */\n    OLED_FillRect(2U, 56U, 12U, 61U, 1U);\n\n    /* 斜线：内部是 Bresenham，纯整数运算 */\n    OLED_DrawLine(14U, 56U, 40U, 61U, 1U);\n\n    /* 空心圆：八分对称，半径 4 的两个圆像一副眼镜 */\n    OLED_DrawCircle(52, 58, 4, 1U);\n    OLED_DrawCircle(64, 58, 4, 1U);\n\n    /* 水平线：x0 和 x1 都会被画（闭区间） */\n    OLED_DrawHLine(72U, 126U, 58U, 1U);\n\n    /* 进度条按千分比填充：光照 0~2000lx 映射到 0~1000。\n     * 内部可用宽 = w-2（去掉边框），且会自动 clamp 到 0~1000。 */\n    permille = (uint16_t)((lx * 1000.0f) / 2000.0f);\n    OLED_ShowProgress(0U, 44U, 128U, 8U, permille);\n}\n\n/* ---- 擦除：图元都有 on 参数，on=0 就是擦 ---- */\nstatic void oled_ui_erase(void)\n{\n    /* 不清全屏，只把刚画的斜线擦掉（on 传 0） */\n    OLED_DrawLine(14U, 56U, 40U, 61U, 0U);\n    (void)OLED_Refresh();\n}\n\n/* ---- 板1 对照：没有图元函数，只能自己用 SetPixel 拼 ----\n * void line_h(uint8_t x0, uint8_t x1, uint8_t y)\n * {\n *     uint8_t x;\n *     for (x = x0; x <= x1; x++) SYS_OLED_SetPixel(x, y, 1U);\n * }\n */",
   "屏的最下面 10 行出现一条完整的边框条，里面有实心块、斜线、两个圆和一段水平线；进度条在 lx=0 时全空、lx=1000 时半满、lx=2000 时全满。\n四个关键检查：① 边框的右边和下边没有被裁掉（说明闭区间算对了）；② 圆的左右上下对称（说明八分对称画法没漏象限）；③ 进度条在 0 和 1000 两个端点没有溢出外框；④ 斜线是连续的单像素宽，没有断点。",
   "闭区间。OLED_DrawRect(x0,y0,x1,y1) 的宽度是 x1-x0+1。想画满 128 列必须写 x1=127，写 x1=128 会被 DrawPoint 静默忽略掉最后一列。\n先画框再填充时， FillRect 会不会盖住边框，板2 的 FillRect 从 y0 填到 y1 全填，会覆盖边框，想要边框可见就要留 1 像素内缩。\n大量 DrawPoint 调用的开销是真实的：板2 的每个公共函数都自己取一次锁（OLED_DrawPoint 内部 OLED_FRAME_LOCK），所以 FillRect 里逐行调 DrawHLine、DrawHLine 再逐列调 DrawPoint，就是几百万次「取锁/放锁」的调用链。递归锁同一个任务只是计数加减，代价可接受，但这就是为什么绘图不要在中断里做、也不要每个像素都套一层自己的 Lock。\n画大幅动态图形（例如实时波形）时，逐点画 + 全屏刷新的开销会让只能做到几 Hz。真正的做法是脏页刷新（见第 10 步），只推变化的那一两页。\n板1 没有 DrawLine/DrawRect/DrawCircle/ShowProgress，用板1 的 API 直接写板2 的例程会编译不过，这是跨板移植最常见的报错来源。",
   "㉓ 本卡的第 4 步 · ㉓ 本卡的第 7 步 · 板2 OLED_DrawLine / OLED_DrawRect / OLED_FillRect / OLED_DrawCircle / OLED_ShowProgress / OLED_DrawHLine / OLED_DrawVLine · 板1 SYS_OLED_SetPixel"
  ],
  [
   "显示字符与字符串：字库取模方向决定成败",
   "屏幕能画图了，接下来要显示文字。这一步的核心知识点只有一个，但它决定了所有文字是否正常：字库的点阵数据是怎么取模的，必须和驱动的取法完全一致。\n\n本项目两板用了两套完全不同的字库和渲染路径，这正是最容易混乱的地方：\n\n板2（oled.c）复用 LCD 的 8×16 字库。 头文件里写着「复用 LCD 的 8x16 ASCII 点阵字库」，源码里 `OLED_ShowChar(x, y, ch, inv)` 的做法是：\n\n    for (i = 0; i < LCD_FONT8X16_H; i++) {\n        row = lcd_font8x16[idx][i];\n        for (j = 0; j < LCD_FONT8X16_W; j++) {\n            bit = (row & (0x80U >> j)) ? 1 : 0;   /* ← 高位在左 */\n            if (inv) bit ^= 1U;                    /* ← 反显 */\n            OLED_DrawPoint(x + j, y + i, bit);\n        }\n    }\n\n看这段要读出三个事实：① 字库是按行存的，每字符 16 字节（16 行），每行的 bit7 是最左边那个像素（`0x80 >> j`）；② 它最终落到 DrawPoint，所以字形正确性完全依赖第 4 步验证过的位序；③ `inv` 参数是靠「对每个位取反」实现的，等于把整个 8×16 字格黑白互换，天然就是「白底黑字」的高亮效果，不需要额外的背景填充逻辑。\n\n因为一个字符高 16 像素 = 2 页、宽 8 像素 = 8 列，所以 128 宽的屏一行放 16 个字符、64 高的屏一共 4 行。这就是本项目所有排版按「4 行 × 16 字符」规划的原因。\n\n板1（sys_oled.c）内置自己的 8×8 字库，而且是「列排」格式。 头文件写得很清楚：内置 8×8 ASCII 点阵已转成「列排」（每列 1 字节，bit0 = 顶端），与页格式显存一一对应，显示字符是「直拷」，零运算。源码 `SYS_OLED_ShowChar(page, x, ch)` 的实现就是：\n\n    oled_buf[(uint16_t)page * SYS_OLED_WIDTH + x + i] = glyph[i];\n\n一次赋值写入一个列字节。因为「列排、bit0 在顶」和「页内 8 行、bit0 在顶」是同一个格式，所以一个字符合计 8 列就是 8 个连续字节，直接 memcpy 式的搬运。这是「字库格式跟着显存格式走」的经典优化。代价是字库只有 8×8（比板2 的 8×16 小一半，且不能反显）。\n\n所以取模方向这件事，本质是：显存是「页/列/低位在上」的格式。任何要用到这里的位图，取模软件的设置必须是 列行式（页模式）+ 低位在上。用错了（行式、高位在上），画出来的字就是旋转/镜像/错位的花字，而且数字节数往往对得上，所以很难一眼看出是取模问题。\n\n最后，字符串层（ShowString）两板行为也不同：板2 自动换行（超出右边界回 x 起点、下移一行，还支持换行转义符强制换行），板1 到右边界就停住不换行。写多行界面的代码时，这个差异会让同一段文字在两块板上长得完全不一样。",
   "① 先显示单个字符 'A'，确认字形正、不歪、不花。\n② 再显示整串 \"hello oled\"，确认字符间距是 8 像素（字格宽），没有重叠。\n③ 显示 16 个字符的一整行，确认正好占满 128 像素。\n④ 在板2 上试 OLED_ShowString(0,0,\"...\",1) 的反显，做高亮效果。\n⑤ 试 OLED_ShowStringCenter，确认居中算法是按 8 像素字格算的。\n⑥ 换到板1 时，把函数的第一个参数从「像素 y」改成「页号 0~7」。",
   "/* ---- 板2：8×16 字库，按行取模，bit7 在左；每字符占 8 列 × 2 页 ---- */\nstatic void oled_text_demo(const SysEnv_t *e)\n{\n    OLED_ClearBuffer();\n\n    /* 居中一行标题（内部按 (128 - len*8)/2 算起点 x） */\n    OLED_ShowStringCenter(0U, \"ENV MONITOR\", 0U);\n\n    /* 分隔线：24 个半角减号的字符串常量 */\n    OLED_ShowString(0U, 16U, \"------------------------\", 0U);\n\n    /* 反显示例：inv=1 是白底黑字，做「选中/报警」的高亮 */\n    OLED_ShowString(0U, 24U, \"ALARM HIGH TEMP\", 1U);\n\n    /* 普通文本 */\n    OLED_ShowString(0U, 40U, \"hello oled\", 0U);\n\n    /* 反斜杠 n 的换行转义是驱动支持的强制换行（板2 独有行为） */\n    OLED_ShowString(0U, 48U, \"line1line2\", 0U);\n\n    (void)OLED_Refresh();\n}\n\n/* 取模方向自查表（画花字时照这个表逐条对）：\n *   显存格式 = 页(8行) / 列 / bit0 在页顶\n *   正确取模 = 列行式（页模式）+ 低位在上\n *   错成「行式」          → 整字旋转 90 度般的错位\n *   错成「高位在上」      → 整字上下镜像\n *   错成「每字符宽度算错」→ 字符之间互相穿插重叠\n *\n * 板2 源码里取模的原始含义（oled.c OLED_ShowChar）：\n *      row = lcd_font8x16[idx][i];               ← 第 i 行一个字节\n *      bit = (row & (0x80U >> j)) ? 1U : 0U;     ← bit7 = 最左像素\n *      if (inv) bit = (uint8_t)(bit ^ 1U);       ← 反显就是逐位取反\n *      OLED_DrawPoint((uint16_t)(x + j), (uint16_t)(y + i), bit);\n */\n\n/* ---- 板1 对照：内置 8×8 列排字库，一个字 = 8 个连续字节直拷 ----\n * void SYS_OLED_ShowChar(uint8_t page, uint8_t x, char ch)\n * {\n *     ... 取 glyph[8] ...\n *     for (i = 0; i < 8U; i++)\n *         oled_buf[(uint16_t)page * SYS_OLED_WIDTH + x + i] = glyph[i];\n * }\n * page 是页号 0~7，不是像素行；且没有 inv 反显参数。\n */",
   "屏上出现居中的 ENV MONITOR 标题、一条 24 字符宽的分隔线、一行反显（白底黑字）的 ALARM HIGH TEMP，以及正常的 hello oled。\n四个检查：① 每个字符字形正（不歪不镜像）；② 字符间距均匀、不重叠；③ 16 个字符正好占满一整行 128 像素；④ 反显那一行确实是「黑字白底」，与相邻的「白字黑底」形成明显对比。",
   "字库取模方向与显存格式必须完全一致（页/列/低位在上）。最常见的误配是「行式 + 高位在上」，画出来的字像被切碎又重排，而且字节数看起来是对的，极具欺骗性。\n板2 的字库复用 lcd_font.h（8×16），板1 用自己的 8×8。两者不能互换，换了就是花字，不是字库坏了，是格式不对。\n一个字符高 16 像素 = 跨 2 页。所以板2 里「一行文字」实际占 2 个页，改一行文字会动到 2 页显存；做脏页刷新时按页判断要这个对应关系。\n字符编码只支持 ASCII 0x20~0x7E：板2 把范围外的字符当空格处理，板1 是「其余字符显示为空格」。所以中文直接显示会是一片空白，不会报错，想显示中文必须自己加中文点阵字库。\n板2 的 `inv` 参数在板1 不存在。从板2 移植文字代码到板1 时，多出来的那个参数会导致编译错误；要发光高亮只能自己画一个 FillRect 当背景。\n板2 的 ShowString 支持换行转义符和自动换行，板1 到右边界停住不换行。用同一份界面代码时，长字符串在板1 上会被直接截断。\n字符串字面量里如果要显示半角双引号，在 C 源码里要写转义；而在本卡片的数据文件里写 C 代码时，字面 CRLF 要写成双反斜杠 r 双反斜杠 n（见本文件开头的数据格式约定）。",
   "㉓ 本卡的第 4 步 · ㉓ 本卡的第 7 步 · 板2 OLED_ShowChar / OLED_ShowString / OLED_ShowStringCenter · 板1 SYS_OLED_ShowChar / SYS_OLED_ShowString · 板2 lcd_font.h 的 lcd_font8x16"
  ],
  [
   "显示数字与浮点：定长对齐、别用 %f",
   "数字显示比字符串多一个陷阱：它的宽度会变。`25`、`-25`、`1013.2`、`-0.5` 的字符数都不同，如果每次都从同一个 x 开始画、却不清掉上一次的残留，屏上就会出现「25.3」变成「25.30」、或者「1013.2」变成「1013.20」这种叠字；若每次全屏清，又会闪。这是嵌入式 UI 的经典问题。\n\n本项目给了两种武器，理解它们的分工很重要：\n\n武器一：先在 RAM 里拼字符串，再整串刷上去。 这是最灵活也最好控的做法，成品代码用的就是它，`snprintf` 把变长的数值格式化成固定宽度（带前导空格）的字符串，然后 `OLED_ShowString` 一次贴上。前导空格会自然覆盖掉上一次的残留字符（空格字符本身就是「8×16 的空白」），所以既不用全屏清、也不会叠字。这也是为什么模板里写 `%6.2f` 而不是 `%f`：宽度固定了，`25.30` 和 `-5.00` 占位一致，数字就不会左右跳。\n\n武器二：驱动自带的数字函数。 板2 有两个：\n\n    OLED_ShowNum(x, y, num, len, inv)          /* uint32，定宽，前导补空格 */\n    OLED_ShowFixed(x, y, val, frac, int_len, inv)  /* 定点小数，不用浮点 */\n\n板2 的 ShowNum 是「定宽显示无符号整数，前导补空格，方便数值原地刷新」，它是无符号的 uint32，负数要自己转或换 ShowFixed。ShowFixed 的示例是 `OLED_ShowFixed(0, 32, 253, 1, 3, 0)` 显示成 ` 25.3`（val=253、frac=1 表示 25.3），它是不用浮点的定点实现，这对没有 FPU 或不想在中断/任务里触发浮点上下文的场景很有价值，参数里的 int_len 控制整数部分宽度。\n\n板1 的武器二不一样：`SYS_OLED_ShowNum(page, x, int32_t num)` 不是定宽（内部就是从左到右逐位输出，负数先画个 '-'），`SYS_OLED_ShowFloat(page, x, value, dec)` 则有专用浮点函数，内部自己做四舍五入和进位（小数进位会回卷到整数部分），dec 最大 3 位。所以板1 反而比板2 更方便直接显示浮点，两板的数字能力相反，这是移植时最容易出错的一处。\n\n「别用 %f」的确切含义：并非「用了会错」，而是许多嵌入式 printf 的浮点支持默认关闭，需要额外链接浮点格式化支持，会显著增加代码量与栈占用。所以本项目成品代码里用 snprintf 的 %f 只出现在「已经确认工具链开了浮点 printf」的场合；更稳妥的路线是先算成整数再格式化（温度 ×100 存 int16，显示时拆成整数位和小数位），这正是 ShowFixed 的思路，也是两条数据链路上通用的做法。\n\n最后别忘了板1 的 `ShowFloat` 会把负数先画 '-'，写定宽对齐时要把它多占的一个字符宽度算进去。",
   "① 先用整型：OLED_ShowNum 显示 0、9、12345，观察宽度变化带来的对齐问题。\n② 用 ShowNum 的 len 参数做定宽：显示值 5、len=5，看是不是「    5」（前导补空格）。\n③ 用 ShowFixed 显示定点小数：val=253、frac=1 → 25.3。\n④ 在板2 上用自家 ShowString + snprintf 做定宽，比较两种做法的灵活性。\n⑤ 连续刷新同一个数值字段（例如每次 +1），确认没有叠字、也没有整屏闪烁。\n⑥ 换到板1 时改用 SYS_OLED_ShowNum / SYS_OLED_ShowFloat， ShowNum 不定宽。",
   "/* ---- 板2：定长对齐的完整做法（成品代码里的那一套） ---- */\nstatic void oled_numbers_demo(const SysEnv_t *e)\n{\n    OLED_ClearBuffer();\n\n    /* 关键：所有变长字段都先格式化成「固定宽度 + 前导空格」的字符串，\n     *   再整串刷上去。前导空格天然覆盖上一次的残留，既不用清屏也不叠字。\n     *   格式化出来的字符串缓存到 s_line_last[]，下一轮还能用来做脏页比较。 */\n    snprintf(s_line_last[0], sizeof(s_line_last[0]),\n             \"T: %6.2f C  \", (double)e->temp_c);\n    snprintf(s_line_last[1], sizeof(s_line_last[1]),\n             \"H: %6.2f %%  \", (double)e->humi_rh);\n    snprintf(s_line_last[2], sizeof(s_line_last[2]),\n             \"P: %7.1f hPa\", (double)e->press_hpa);\n    snprintf(s_line_last[3], sizeof(s_line_last[3]),\n             \"L: %5u lx  \", (unsigned)e->light_lx);\n\n    OLED_ShowString(0U, 24U, s_line_last[0], 0U);\n    OLED_ShowString(0U, 32U, s_line_last[1], 0U);\n    OLED_ShowString(0U, 40U, s_line_last[2], 0U);\n    OLED_ShowString(0U, 48U, s_line_last[3], 0U);\n\n    (void)OLED_Refresh();\n}\n\n/* ---- 完全避开浮点 printf 的路线：定点数自己拆 ---- */\nstatic void oled_fixed_demo(int16_t temp_x100)\n{\n    int32_t v = (int32_t)temp_x100;      /* 2530 = 25.30C */\n    uint8_t neg = 0U;\n\n    if (v < 0) { neg = 1U; v = -v; }\n    OLED_ShowString(0U, 32U, neg ? \"T: -\" : \"T:  \", 0U);\n    OLED_ShowNum(24U, 32U, (uint32_t)(v / 100), 2U, 0U);   /* 整数位，定宽 2 */\n    OLED_ShowString(40U, 32U, \".\", 0U);\n    OLED_ShowNum(48U, 32U, (uint32_t)(v % 100), 2U, 0U);   /* 两位小数，定宽 2 */\n    OLED_ShowString(64U, 32U, \" C\", 0U);\n    (void)OLED_Refresh();\n}\n\n/* ---- 板1 对照：有专用浮点函数，但 ShowNum 不定宽 ----\n * SYS_OLED_ShowNum(2, 0, -1234);           函数式，内部逐位输出，不是定宽\n * SYS_OLED_ShowFloat(2, 48, 25.43f, 1);    专用浮点，四舍五入，dec 最大 3\n *   例：25.43f, dec=1 → 屏上显示 25.4\n * 小数进位会回卷到整数部分；负数会先画一个 '-'，占 1 个字符宽。\n */",
   "连续刷新同一个数字字段（例如每秒 +1），屏上数字原地变化：① 没有出现「12」和「3」叠成「123」以外的残留；② 位数变长变短时不会左右跳动；③ 全屏不闪。\n对温度做一次极端测试：从 25.30 变到 -5.00，再变到 1013.2，三次都保持列对齐。\n再验一次「不用浮点」的那条路：把 temp_x100=2530 与 253、-5 都跑一遍，输出分别是 25.30、2.53、-0.05。",
   "定宽靠前导空格，不是靠清屏。以为「每次都 Clear 一下就好」的做法会闪，而且会中断其他区域的显示（局部刷新时尤其明显）。\n板2 的 `OLED_ShowNum` 是 uint32、且有 len 参数（定宽）；板1 的 `SYS_OLED_ShowNum` 是 int32、没有 len（不定宽）。同名不同参、连符号性都相反，这是两板最容易搞混的一对函数，必须查源码确认。\n浮点能力也是反的：板2 没有 ShowFloat（要用 ShowFixed 做定点，或自己 snprintf），板1 有 SYS_OLED_ShowFloat。别按名字想当然。\n`%f` 能不能用取决于工具链有没有开浮点 printf 支持。没开时链接会报 undefined reference to _printf_float 之类，或者干脆不输出，所以成品代码优先走「乘 100 存整数 + 自己拆显示」这条路。\n`snprintf` 吃栈：成品代码给显示任务开 512 字（word）栈，就是为了容纳带格式化的调用链。栈给小了会 HardFault，而且现象是「偶发死机」，极难定位。\n小数进位别忘了：25.999 显示 1 位小数应当是 26.0，不是 25.9。板1 的 ShowFloat 内部处理了 `if (frac >= scale) { frac -= scale; ip++; }`，自己实现时要照做。",
   "㉓ 本卡的第 6 步 · ㉓ 本卡的第 8 步 · 板2 OLED_ShowNum / OLED_ShowFixed · 板1 SYS_OLED_ShowNum / SYS_OLED_ShowFloat"
  ],
  [
   "多任务下的整帧加锁：40 次事务不能被插进来",
   "这一步是本项目 OLED 部分真正的难点，也是它和「网上抄个 OLED 驱动」最大的区别。\n\n先看问题的规模。 板2 的 OLED_Refresh 是「逐页写」：8 页，每页先发一条 3 字节的定位命令（页地址 0xB0|p、列低 0x00、列高 0x10），再把 128 字节显存分成 4 块（OLED_CHUNK = 32）发出去。所以刷一屏 = 8 × (1 + 4) = 40 次独立的 I2C 事务，整屏 1024 字节在 400kHz 下约 23~25ms。\n\n问题来了：这 40 次事务之间不是原子的。 FreeRTOS 是抢占式调度，I2C1 上还挂着 24C02（0x50）和 MPU6050（0x68）。如果显示任务刷到第 3 页时被抢占，另一个任务插进来发了一条 MPU6050 的读事务，然后显示任务接着刷第 4 页，同一帧的 40 次事务被别的器件插断了。后果并非「数据错」，而是屏上出现一半新一半旧的横向撕裂条：上半屏是这一帧的内容，下半屏是上一帧的。因为写进去的每一页本身都是合法的，只是它们不属于同一帧。\n\n解决方案：整帧持锁。 项目在 sys_i2c 里提供了每总线一把的递归互斥量：`SYS_I2C_Lock(bus)` / `SYS_I2C_Unlock(bus)`。板2 的 oled.c 用两个宏包住：\n\n    #define OLED_FRAME_LOCK()    SYS_I2C_Lock(OLED_I2C_ID)\n    #define OLED_FRAME_UNLOCK()  SYS_I2C_Unlock(OLED_I2C_ID)\n\n而 OLED_Refresh 内部整段就持着这把锁，从第 1 页到第 8 页，一次都不放。\n\n为什么要用「递归」锁？ 因为 oled.c 里每个公共函数都自己取锁（ClearBuffer、DrawPoint、ShowChar……全都取）。于是会出现「外层包一段 → 内层函数各自再取」的嵌套：`OLED_Clear()` 取锁 → 调 `OLED_ClearBuffer()`（再取一次）→ 调 `OLED_Refresh()`（再取一次）。如果锁不能重入，同一个任务第二次 Lock 就会把自己锁死（经典的死锁）。递归锁的语义是「同一任务重复 Lock 只是计数 +1，配对 Unlock 递减」，所以这种嵌套天然安全。\n\n为什么绘图函数（只改 RAM）也要取锁？ 因为它们会和 Refresh 并发。如果刷到第 5 页时另一个任务改了显存，那第 5~8 页推上去的就不是同一帧的内容，同一块显存被写的同时被读。锁保护的既是「总线」这个共享资源，也是「帧缓冲」这个共享资源。\n\n代价必须讲明白： 整帧持锁期间，MPU6050 / 24C02 的读事务进不来，要等 20ms 量级。这是「整帧不可插入」的必然代价，不是可以优化掉的 bug。所以：\n- 刷屏频率要克制（成品代码限到 5Hz，并给传感器留空档）；\n- 绝对不要在中断里调用任何 OLED 公共函数，sys_i2c 用 `__get_IPSR()` 判断中断上下文并自动跳过加锁，在中断里调用等于「无锁直冲」，同时 20ms 级的刷屏会直接毁掉实时性；\n- 加锁不关中断、也不该关：用 `__disable_irq` 保护 23ms 的刷屏会把整个系统的时间基准搞崩；\n- 上电初始化阶段（调度器未启动）加锁是空操作，那时单线程，本来就没有并发，所以安全。\n\n板1 的实现思路一样，但规模小得多：它用水平寻址模式设好「整屏窗口」（0x21 设列 0~127、0x22 设页 0~7），然后一次事务把 1024 字节流水发完。整帧只有 1~2 次事务，仍然持锁，但被插断的窗口小得多。",
   "① 确认 sys_i2c 的锁是每总线一把、递归的（sys_i2c.h 区块 2b 有完整语义说明）。\n② 用 OLED_FRAME_LOCK/UNLOCK 宏包住「改显存 + 推屏」的整段操作。\n③ 验证嵌套安全：OLED_Clear() 内部会嵌套三层取锁，跑起来不该卡死。\n④ 造一个并发场景：让显示任务持续刷屏，同时另一个任务高频读 MPU6050，看屏上有没有撕裂条。\n⑤ 检查中断：确认没有任何 OLED 调用出现在 ISR 里。\n⑥ 测一次最坏情况：拔掉屏，看 OLED_Refresh 因重试+超时放大到数百毫秒时，任务有没有降级处理。",
   "/* ---- 板2：整帧持锁（源码 OLED_Refresh 的骨架） ---- */\nuint8_t OLED_Refresh(void)\n{\n    uint8_t  p;\n    uint16_t off;\n    uint8_t  fail = 0U;\n\n    /* 40 次事须须在同一临界区内，否则别的器件会插进这一帧，\n     *   屏上就是「一半新一半旧」的撕裂横条。 */\n    OLED_FRAME_LOCK();\n\n    for (p = 0U; p < OLED_PAGE_CNT; p++) {\n        uint8_t page_ok = 1U;\n        uint8_t pos[3];\n\n        /* 3 条定位命令合并成一次事务：页地址 + 列低 + 列高 */\n        pos[0] = (uint8_t)(0xB0U | p);\n        pos[1] = 0x00U;\n        pos[2] = 0x10U;\n        if (oled_wr(0x00U, pos, 3U) != 0U) page_ok = 0U;\n\n        /* 一页 128 字节，按 OLED_CHUNK = 32 分成 4 块 */\n        for (off = 0U; off < OLED_WIDTH; off += OLED_CHUNK) {\n            uint16_t n = OLED_CHUNK;\n            if ((uint16_t)(off + n) > OLED_WIDTH) n = (uint16_t)(OLED_WIDTH - off);\n            if (oled_wr(0x40U, &oled_buf[p][off], n) != 0U) page_ok = 0U;\n        }\n\n        if (page_ok == 0U) fail++;      /* 返回失败页数，调用方可降级 */\n    }\n\n    OLED_FRAME_UNLOCK();\n    return fail;\n}\n\n/* ---- 应用层：把「一组绘图 + 一次推屏」整体原子化 ---- */\nstatic uint8_t oled_frame_flush(const SysEnv_t *e)\n{\n    uint8_t fail;\n\n    /* 外层再包一层锁：保证从「开始改显存」到「推屏结束」之间，\n     * 没有任何别的任务能看到半成品的显存。内层 OLED_Refresh 自己\n     * 也会取锁，递归锁允许重入，不会自锁死。 */\n    SYS_I2C_Lock(SYS_I2C_1);\n    oled_text_demo(e);\n    oled_ui_demo(e);\n    fail = OLED_Refresh();\n    SYS_I2C_Unlock(SYS_I2C_1);\n\n    return fail;\n}\n\n/* ---- 板1 对照：整帧一次性流水发出（水平寻址模式） ----------------\n * SYS_OLED_Refresh() 内部：\n *     tmp[0]=0x21; tmp[1]=0x00; tmp[2]=127;  ← 设列窗口 0~127\n *     tmp[0]=0x22; tmp[1]=0x00; tmp[2]=7;    ← 设页窗口 0~7\n *     然后一次事务把 1024 字节全部发出。\n * 事务数少，但同样持锁；代价是长事务期间总线被独占的时间反而更集中。\n */",
   "屏上不再出现「上半屏新、下半屏旧」的横向撕裂条，即使另一个任务在高频读 MPU6050。\n三个可观测的验证点：① 让显示任务以 20Hz 疯狂刷屏、同时让 I2C 读任务以 200Hz 读 MPU6050，观察 1 分钟无撕裂；② 串口打印一次刷屏耗时，应当在 23~25ms（400kHz）；③ 最坏情况测试：刷屏期间读 MPU6050 的耗时会被拉长到 20ms 量级，这是预期行为，不是故障，日志里看到它变慢不要去「修」。",
   "中断里调用 OLED 任何公共函数都是错的：sys_i2c 检测到中断上下文会自动跳过加锁，于是在中断里既没有互斥保护，又会因为 20ms 级刷屏拖垮整个实时性。ISR 里要显示，只能发队列/信号量把活交给任务。\n不要用 `__disable_irq` / `taskENTER_CRITICAL` 来保护刷屏。锁的设计就是「让出 CPU 等」，不关中断；关 23ms 中断会直接毁掉系统时间基准（tick、串口、ADC 全都受影响）。\n递归锁是这套写法成立的前提。如果换成普通二值信号量，OLED_Clear → ClearBuffer → Refresh 这条嵌套链会在第二次 Lock 处自死锁，而且现象是「一调用就卡住」，很容易误判成硬件问题。\n代价要心里有数：整帧持锁期间，24C02 存日志、MPU6050 取姿态都要排队等 20ms 量级。如果控制回路里 MPU6050 是 1kHz 采样的，那显示刷新频率就必须压到很低（或改成脏页刷新），否则姿态控制会被屏拖垮。\nRefresh 的返回值必须处理。屏没插好时，每次 oled_wr 会重试 OLED_RETRY=3 次并等 I2C 超时，最坏可以把 23ms 放大到数百毫秒。成品代码的做法是失败后降级到 2 秒一次，避免显示任务把 CPU 和总线都占死。\n板2 的 `OLED_IsOnline()` 只看「发地址有没有应答」，「能寻址」不等于「写得进去」：上拉不足或走线过长时它仍返回 1。判断「到底写没写进去」要看 OLED_Refresh() 的返回值和 OLED_ErrCount()。",
   "㉓ 本卡的第 3 步 · ㉓ 本卡的第 10 步 · ① FreeRTOS 任务 · ⑧ I2C 总线 · SYS_I2C_Lock · SYS_I2C_Unlock · SYS_I2C_COUNT · SYS_I2C_WriteBytes · 板2 OLED_Refresh / OLED_ErrCount / OLED_LastErr"
  ],
  [
   "接进 FreeRTOS 显示任务，和传感器数据对接",
   "到这里屏本身完全能用了。但必须如实说明本项目的现状：这两个 OLED 模块目前全工程没有调用者。板2 的 `OLED_Init` 只在 `oled.c:101` 定义，板1 的 `SYS_OLED_Init` 只在 `sys_oled.c:259` 定义，两板的 `main.c` 都没有 include 对应的头、也没有调用，它是一套写好但还没接线的驱动。这一步要把现有任务真正接进去，而非「改现有任务」，是本卡的核心交付步骤。\n\n第一步：解耦。 显示任务绝不能自己去做传感器读取。原因有三：① 传感器读取的时序要求（例如 DHT11 的微秒级时序、MPU6050 需要在固定周期采样）和刷屏的 23ms 阻塞互相冲突；② 刷屏期间持锁 20ms，采集任务不该被连带阻塞；③ 采集频率和显示频率天然不同（采集可能 10Hz，人眼 5Hz 就够）。所以正确结构是：采集任务 → 队列 → 显示任务。\n\n第二步：队列的取舍。 显示是「要最新值」而不是「要每一个值」的典型场景，所以：队列长度不用大（4 足够），而且显示任务拿到一帧后应该把队列里压着的旧数据全部抽干、只留最后一条（成品代码里那个 while 循环就是在做这件事）。如果老老实实按 FIFO 一条条显示，会永远在追历史，屏上显示的是几秒前的数据。\n\n第三步：限速与降级。 人眼 5Hz 完全够，所以加一个 tick 判断，200ms 没到就 vTaskDelay 让出 CPU。降级路径也必须有：OLED_Refresh 返回非 0（有页没写成功）时，把刷新周期放慢到 2 秒，避免在屏故障时反复重试把系统拖垮；同时累计 s_oled_refresh_ok / s_oled_refresh_bad 两个计数，遥测里能看到屏的健康度。\n\n第四步：任务参数。 显示任务的优先级应当低于采集和控制任务，刷屏是慢活，绝不能挡着急着跑的控制回路；栈要给足（成品代码给 512 字），因为 snprintf 带格式化的调用链吃栈。\n\n第五步：异常态要有画面。 传感器掉线时（online==0）不能只是继续显示旧值，那会让操作员以为数据是新的。正确做法是整屏换成醒目的告警画面（成品代码里用反显的 ALARM 强调）。显示系统的职责之一是让异常显眼，不是让画面好看。\n\n最后：上电自检画面。 成品代码在任务开头调了一次 oled_bitselfcheck 并停 1 秒，保留一个「屏自己能证明自己活着」的画面，在现场排障时极其有用。",
   "① 在 main 里（或者一个 app_oled_start 里）创建队列和两个任务：采集任务、显示任务。\n② 采集任务周期采数据、xQueueSend 塞进队列，不碰 OLED。\n③ 显示任务：xQueueReceive 拿数据 → 抽干队列只留最新 → 限速判断 → 调 oled_frame_flush。\n④ 加降级：Refresh 返回值非 0 就放慢到 2 秒一次，并累计好坏计数。\n⑤ 加异常画面：传感器 offline 时整屏换告警画面（用 inv=1 反显强调）。\n⑥ 确认优先级与栈：显示任务优先级低于采集/控制，栈 512 字起。\n⑦ 确认工程里真的 include 了 oled.h 并加入了 oled.c（现状是两板 main.c 都没接，必须自己加）。",
   "/* ---- 显示任务：队列解耦 + 限速 + 降级 + 异常画面 ---- */\nstatic void vTaskOled(void *pv)\n{\n    SysEnv_t e;\n\n    (void)pv;\n    memset(&e, 0, sizeof(e));\n\n    if (oled_setup() != 0U) {\n        printf(\"[OLED] 初始化失败，显示任务退出（通讯部分继续跑）\\r\\n\");\n        vTaskDelete(NULL);      /* 屏坏了不该拖垮整个系统 */\n        return;\n    }\n\n    oled_bitselfcheck();                       /* 上电自检画面，留 1 秒 */\n    vTaskDelay(pdMS_TO_TICKS(1000));\n\n    for (;;) {\n        if (xQueueReceive(s_env_q, &e, pdMS_TO_TICKS(500)) == pdPASS) {\n            /* 抽干队列只留最新：显示要的是「现在」，不是「历史」。\n             *   按 FIFO 一条条显示会永远在追旧数据。 */\n            SysEnv_t newer;\n            while (xQueueReceive(s_env_q, &newer, 0) == pdPASS) e = newer;\n        }\n\n        /* 限速 5Hz：人眼足够，也给 I2C 总线留出给传感器的空档 */\n        if ((xTaskGetTickCount() - s_oled_tick_last) < pdMS_TO_TICKS(200)) {\n            vTaskDelay(pdMS_TO_TICKS(20));\n            continue;\n        }\n        s_oled_tick_last = xTaskGetTickCount();\n\n        if (e.online == 0U) {\n            /* 异常必须显眼：整屏换告警，反显强调，\n             *   绝不能让操作员把旧数据当新数据看。 */\n            OLED_ClearBuffer();\n            OLED_ShowStringCenter(0U, \"SENSOR OFFLINE\", 0U);\n            OLED_ShowStringCenter(16U, \"check wiring\", 0U);\n            OLED_ShowStringCenter(32U, \"ALARM\", 1U);\n            (void)OLED_Refresh();\n            vTaskDelay(pdMS_TO_TICKS(500));\n            continue;\n        }\n\n        if (oled_frame_flush(&e) == 0U) {\n            s_oled_refresh_ok++;\n        } else {\n            /* 降级：写不进去时放慢到 2 秒一次，别让重试+超时把系统拖死 */\n            s_oled_refresh_bad++;\n            vTaskDelay(pdMS_TO_TICKS(2000));\n        }\n        vTaskDelay(pdMS_TO_TICKS(20));\n    }\n}\n\n/* ---- 采集任务：只管采数据、塞队列，完全不碰 OLED ---- */\nstatic void vTaskEnv(void *pv)\n{\n    SysEnv_t e;\n\n    (void)pv;\n    for (;;) {\n        e.temp_c    = 25.3f;\n        e.humi_rh   = 61.8f;\n        e.press_hpa = 1013.2f;\n        e.light_lx  = 420U;\n        e.mpu_ax    = 12;\n        e.online    = 1U;\n        (void)xQueueSend(s_env_q, &e, 0);\n        vTaskDelay(pdMS_TO_TICKS(100));\n    }\n}\n\n/* ---- 任务创建：显示任务优先级低于采集 ---- */\nvoid app_oled_start(void)\n{\n    s_env_q = xQueueCreate(4U, sizeof(SysEnv_t));\n    if (s_env_q == NULL) return;\n\n    (void)xTaskCreate(vTaskOled, \"OLED\", 512U, NULL, 2U, NULL);  /* 慢活，优先级低 */\n    (void)xTaskCreate(vTaskEnv,  \"ENV\",  256U, NULL, 3U, NULL);  /* 采集优先 */\n}\n\n/* ---- 板1 对照：把 oled_setup 里那几行换成 ----\n * if (SYS_OLED_Init(SYS_I2C_1, SYS_OLED_I2C_ADDR) != 0U) { ... }\n * 其余任务结构、队列、限速、降级逻辑完全一样。\n */",
   "上电后屏上先出现自检画面（bit selfcheck / PASS）停 1 秒，然后开始以 5Hz 刷新环境数据；把传感器拔掉（或把 e.online 置 0），屏上立刻变成 SENSOR OFFLINE / ALARM 的反显告警画面。\n三个可观测点：① s_oled_refresh_ok 单调增长、s_oled_refresh_bad 不涨；② 采集任务的工作没有被刷屏拖慢（采集周期稳定在 100ms，不因为刷屏抖到 130ms）；③ 屏上数值和串口日志里的数值一致且是同一时刻的（说明抽干队列只留最新这一招起作用了）。",
   "本项目的现状要认清：板2 的 OLED_Init 只在 oled.c:101 定义、板1 的 SYS_OLED_Init 只在 sys_oled.c:259 定义，两板 main.c 都没有接。所以第一步是把它 include 进工程并加入构建，别以为「驱动写好了就代表跑起来了」。\n别让显示任务自己去读传感器。刷屏持锁 20ms，传感器读取被它挡住会让采集周期抖动；DHT11 这类微秒级时序的器件更是直接读失败。一律走队列。\n队列不要按 FIFO 消费，要「抽干只留最新」，否则屏上永远显示几秒前的数据，这个 bug 的迷惑性在于「数据是对的，只是旧的」。\n显示任务优先级不要给高。刷屏是慢活，优先级给高了会把控制回路挤掉，现象是「一开屏电机就抖」。\n栈要给足（512 字起）：snprintf 带浮点格式化的调用链吃栈，给少了是偶发 HardFault，最难查。\n屏故障要能降级而不是死循环重试：OLED_Refresh 失败时重试 3 次 + 等 I2C 超时，最坏数百毫秒；不给降级的话，屏一坏整个系统的实时性就没了。\n异常态必须换画面。继续显示旧值等于误导操作员，这是显示系统设计上的硬要求，不是可选项。",
   "① FreeRTOS 任务 · ⑱ SPI Flash 断网缓存日志 · ⑲ LoRa E22 点对点 · ㉒ 自定义帧协议 · ⑧ I2C 总线 · 板2 oled.c / oled.h · 板1 sys_oled.c / sys_oled.h"
  ],
  [
   "性能优化：脏页刷新、400kHz、以及该不该换 SPI",
   "最后一步解决「屏能跑了，但跑得不够快/不够省」的问题。先把账算清楚，才知道该优化哪里。\n\n当前的开销账本（板2）： 整帧刷新 = 40 次 I2C 事务、1024 字节数据、约 23~25ms，而且整段持锁，这 23ms 里总线上其他从机全都得等。如果显示任务以 5Hz 刷，那就是每秒 125ms 的总线被独占（12.5%）；如果脑子一热做到 50Hz，就是 1.25 秒/秒，总线直接被屏吃光，MPU6050 读一次要排队 20ms 以上，姿态控制必然崩。优化的目标并非「让屏更快」，而是让同样信息量占用更少的总线时间。\n\n优化一：只刷变化的页（脏页刷新），收益最大。 一页 = 竖直 8 像素。本项目一行 8×16 文字正好占 2 页，所以「哪几行变了」直接对应「哪几页脏了」。环境监测这类界面，通常只有 1~2 行数值在变，也就是 2~4 页；把整帧 8 页换成 3 页，刷屏时间从 23ms 直接降到 8~9ms 量级（板2 约 3 页 × 5 次事务 = 15 次事务）。要落地它，需要仿照 OLED_Refresh 的逐页写法给 oled.c 加一个 `OLED_RefreshPage(page)`，换算法不换硬件，改动很小，收益立竿见影。\n\n判断「脏」的办法就是成品代码里那套：每一次刷新前，先把新的一行文本和上一轮的文本快照（s_line_last）逐行比较，不一样的行才重画、才标记对应的页。\n\n优化二：把总线提到 400kHz。 本项目两板初始化时都已经用 400kHz 了（板1 内部 SYS_I2C_Init(bus, 400000)，板2 由调用方 SYS_I2C_Init(SYS_I2C_1, 400000)）。从 100kHz 提到 400kHz 是 4 倍带宽，但要两条：① 总线上其他从机必须也支持（24C02 支持 400kHz，MPU6050 支持到 400kHz）；② 400kHz 对上升沿更敏感，上拉不足或走线过长时会开始出错，现象是「原来 100kHz 好好的，改成 400kHz 就偶尔花屏」。所以提速前先确认上拉和走线。\n\n优化三：降通信量的另一条路，只传变化区域。 如果屏的大部分是静态框线，可以只在初始化时画一次框，之后每次只重画数值区域。这跟「脏页」是同一思路的两种粒度（页粒度 vs 区域粒度），但要 SSD1306 的页模式限制：一笔数据事务不能跨页，所以区域刷新仍要按页拆。\n\n优化四：换个接口，SPI 版 SSD1306。 同样的屏有 SPI 版本。SPI 没有地址寻址、没有应答、没有仲裁，时钟可以到 10MHz 以上，把 1024 字节推出去只要约 1ms，比 I2C 快 20 倍以上；而且它独占总线，不会和 24C02/MPU6050 抢。代价是占 4~5 根线（SCLK/MOSI/CS/DC/RES）、不能再和其他 I2C 器件共享排针，而且要SPI 版 SSD1306 没有「控制字节」这个概念，改成用 DC 引脚区分命令/数据，驱动要重写低层（oled_wr 那一层）。如果屏刷新成了系统瓶颈、或者 I2C 总线太挤，换 SPI 版是最彻底的解法。\n\n优化五：别刷那么勤。 人眼对 5Hz 的数值刷新完全不敏感（尤其是数字只在变化时才需要看到），把频率从 20Hz 降到 5Hz 直接省 75% 的总线时间，代价为零。这是性价比最高的一招，很多人却忽略了。",
   "① 先量基线：在刷新前后读 DWT 或 tick，打印一次全屏刷新的实际耗时，确认是不是 23~25ms。\n② 统计页面变化率：给每个页加 dirty 标记，打印每轮真正变了几页。\n③ 实现脏页刷新：仿照 OLED_Refresh 逐页写，给 oled.c 加 OLED_RefreshPage(page)，只刷脏页。\n④ 再量一次耗时，对比基线（预期 3 页时 8~9ms）。\n⑤ 检查上拉与走线后，确认 400kHz 稳定（连续刷新 10 分钟不出错）。\n⑥ 如果仍不够快、且总线太挤，评估换 SPI 版 SSD1306（要重写低层 + 改接 4~5 根线）。",
   "/* ---- 脏页刷新的落地骨架 ----\n * ① 每轮先把新文本格式化成 4 行，和上一次的快照逐行比较；\n * ② 变了的那一行 → 标记它覆盖的两页为 dirty（一行 8×16 文字 = 2 页）；\n * ③ 只把 dirty 的页推上屏。\n */\n\n/* 行 → 页的映射：一行 8×16 文字占竖直 16 像素 = 2 页 */\n#define LINE_TO_PAGE(line)   ((uint8_t)((line) * 2U))\n\nstatic void oled_mark_dirty(const char line_new[4][24], uint8_t dirty[8])\n{\n    uint8_t i;\n\n    for (i = 0U; i < 4U; i++) {\n        if (strcmp(line_new[i], s_line_last[i]) != 0) {\n            uint8_t p = LINE_TO_PAGE(i);\n            dirty[p]     = 1U;      /* 该行上半 */\n            dirty[p + 1] = 1U;      /* 该行下半 */\n            strncpy(s_line_last[i], line_new[i], sizeof(s_line_last[i]) - 1U);\n            s_line_last[i][sizeof(s_line_last[i]) - 1U] = 0;\n        }\n    }\n}\n\n/* 需要的驱动增强：仿照 OLED_Refresh 的逐页体，只写一页。\n * 本项目 oled.c 目前只提供整帧 OLED_Refresh()，所以这一步是\n * 「给驱动加一个函数」，不是改硬件。加完立刻有 8~9ms 量级的效果。 */\n\n/* ---- 参数速查：本项目两板的实际取值 ---- */\n/*   OLED_WIDTH      128        屏幕宽（列）\n *   OLED_HEIGHT     64         屏幕高（行）\n *   OLED_PAGE_CNT   8          页数 = 64/8\n *   OLED_CHUNK      32         一笔数据事务最大字节数（一页分 4 块）\n *   OLED_RETRY      3          每笔事务失败重试次数\n *   OLED_ADDR       0x3C       7 位地址（模块背面标 0x78 是 8 位）\n *   OLED_I2C_ID     SYS_I2C_1  I2C1 = PB8(SCL)/PB9(SDA)\n *   SYS_I2C_TIMEOUT 2000000    等标志位的最大循环次数（防死等）\n *   刷新耗时        约 23~25ms 40 次事务 / 1024 字节 @400kHz\n */\n\n/* ---- SPI 版 SSD1306 的差异（要换接口时看这一条） ----\n *   I2C 版：每笔事务首字节是控制字节 0x00(命令) / 0x40(数据)，共用总线要加锁\n *   SPI 版：没有控制字节，改用一根 DC 引脚区分命令/数据，另有 CS 片选\n *           （有的还有 RES 复位脚）；独占总线、无需互斥、时钟可上 10MHz+\n *   驱动改动集中在低层 oled_wr 那一层，上层绘图/文字代码可以原样复用。\n */",
   "基线耗时打印出来应当是 23~25ms（400kHz、无重试）。实现脏页刷新后，静态界面（只有 1 行数值在变）每轮耗时应当降到 8~9ms 量级，且 s_oled_refresh_ok 持续增长无失败。\n再验证省下的时间真的还给了总线：刷屏期间读一次 MPU6050，优化前耗时在 20ms 量级，优化后应当明显缩短。\n如果决定不换硬件，把刷新频率从 20Hz 降到 5Hz，用同样的方法测一次，也应当看到总线占用时间降到 1/4。",
   "脏页刷新的前提是干净的显存快照。如果程序在别处也会改显存（例如另一个任务画波形），那 s_line_last 这套比较就失效了，要么所有写显存的操作都走同一个地方，要么用一个统一的「脏区域」标记机制。\n400kHz 不是无条件的。「原来 100kHz 好好的，改 400kHz 就偶尔花屏」是上拉不足/走线过长的经典症状，不是代码问题，先查上拉电阻和线长，再查代码。\n页模式下一笔数据事务不能跨页（SSD1306 写到页尾会回到本页开头，而不是进下一页），所以「只刷某个区域」也仍然要按页边界拆开。板1 用的是水平寻址模式，一次 1024 字节可以自动跨页，两板的优化写法不能照搬。\n换 SPI 版不是「改个宏」：控制字节没了、要加 DC 引脚、上层要处理 CS，低层 oled_wr 必须重写。但上层（DrawPoint / ShowChar / 绘图）可以原样复用，分层做得好，换接口的代价就只在最下面一层。\n优化优先级建议：先降频率（零成本）→ 再脏页刷新（小改动、收益大）→ 最后才考虑换硬件。若直接换 SPI 版，往往是在解决一个「刷太勤」造成的伪瓶颈。\n别为了刷得快就去掉整帧锁。去掉锁换来的是撕裂画面和偶发数据错，那不是优化，是引入 bug。",
   "㉓ 本卡的第 5 步 · ㉓ 本卡的第 8 步 · ㉓ 本卡的第 9 步 · ⑧ I2C 总线 · ⑱ SPI Flash 断网缓存日志 · 板2 OLED_Refresh / OLED_CHUNK / OLED_RETRY / OLED_PAGE_CNT"
  ]
 ]}
"""
